local KTool = CS.Engine.Lib.KTool
------------ import ------------

------------ define ------------
------------ define ------------

---@class UIActivityMainSingleSignCellNode
---@field Effect                        	UnityEngine.RectTransform
---@field HasReceived                   	UnityEngine.RectTransform
---@field Tomorrow                      	UnityEngine.RectTransform
---@field CanReceive                    	UnityEngine.RectTransform
---@field BtnNode                       	UnityEngine.UI.Button
---@field GoodNode                      	Engine.Modules.LuaBehaviour
---@field TextNumber                    	TMPro.TextMeshProUGUI
---@field ImgBg                         	UnityEngine.UI.Image

---@field BtnCardSigninNode             	UnityEngine.UI.Button
---@field ImgRole                       	UnityEngine.UI.RawImage
local UIActivityMainSingleSignCellNode = Class("UIActivityMainSingleSignCellNode")
function UIActivityMainSingleSignCellNode:__init()
    self.btnAction = nil

end

function UIActivityMainSingleSignCellNode:__delete()
    self.btnAction = nil

    self.controller = nil
end

---SetCallBack
---设置单击回调函数
function UIActivityMainSingleSignCellNode:SetBtnCallBack(cb)
    self.btnAction = cb
end

function UIActivityMainSingleSignCellNode:Awake()
    if self.BtnNode then
        SetButtonAction(self.BtnNode, function ()
            if type(self.btnAction) == 'function' then
                self.btnAction()
            end
        end)
    end
    if self.BtnCardSigninNode then
        SetButtonAction(self.BtnCardSigninNode, function ()
            if type(self.btnAction) == 'function' then
                self.btnAction()
            end
        end)
    end
end

function UIActivityMainSingleSignCellNode:FreshBaseUI(data, isTomorrow)
    self:FillDayText(data.accumulativeLoginNum)
    self:FillDrawStatus(data.status, isTomorrow)
    KTool.SetActive(self.Effect, checkInt(data.status) == Constants.GetStatus.Can)
    self:FillGoodsNode(data)
end

function UIActivityMainSingleSignCellNode:FreshFinalUI(data, isTomorrow)
    self:FillDayText(data.accumulativeLoginNum)
    self:FillImgRole(data)
    self:FillDrawStatus(data.status, isTomorrow)
end
---显示天数
function UIActivityMainSingleSignCellNode:FillDayText(day)
    self.TextNumber.text = day
end

---签到情况
function UIActivityMainSingleSignCellNode:FillDrawStatus(status, isTomorrow)
    KTool.SetActive(self.Tomorrow, checkBool(isTomorrow))
    KTool.SetActive(self.CanReceive, checkInt(status) == Constants.GetStatus.Can)
    KTool.SetActive(self.Effect, checkInt(status) == Constants.GetStatus.Can)
    KTool.SetActive(self.HasReceived, checkInt(status) == Constants.GetStatus.Has)
end

---填充人物立绘
function UIActivityMainSingleSignCellNode:FillImgRole(data)
    local goodsId = data.rewards[1].goodsId
    local goodsType = GoodsUtils.GetIdType(goodsId)
    local isCardOrSkin = goodsType == Constants.IDType.CharacterCard or goodsType == Constants.IDType.CardSkin
    KTool.SetActive(self.ImgRole, isCardOrSkin)
    KTool.SetActive(self.GoodNode, not isCardOrSkin)
    KTool.SetActive(self.Effect.transform:Find("UIFX_SingleSignPanelIcon"), not isCardOrSkin)
    if isCardOrSkin then
        local path = CardConfMgr:GetInstance():GetCardDefaultBodyIconPath(goodsId)
        CfUtils.FillImage(self.ImgRole, path)
    else
        self:FillGoodsNode(data)
    end
end

function UIActivityMainSingleSignCellNode:FillGoodsNode(data)
    local rewards = data.rewards[1]
    local nodeEnv = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
    if nodeEnv then
        nodeEnv:SetClickButtonAction(function()
            if checkInt(data.status) == Constants.GetStatus.Can then
                if type(self.btnAction) == 'function' then
                    self.btnAction()
                end
            else
                self:ShowGoodsTips(rewards)
            end
        end)
        nodeEnv:Reload(
            {
                goodsId = checkInt(rewards.goodsId),
                isShowNo = true, text = 'x' .. tostring(rewards.num)
            }
        )
    end
end

function UIActivityMainSingleSignCellNode:ShowGoodsTips(rewards)
    local goodsId = rewards.goodsId
    local  vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    if isTable(vo) then
        GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, vo.name, vo.descr, vo.quality, vo.id)
    end
end

function UIActivityMainSingleSignCellNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return UIActivityMainSingleSignCellNode